          "在我以往的20多年人生里，文学对我的影响比较深，断断续续写过一点点文字，朋友和老师都有鼓励过我继续写下去，但是因为一些私人原因，可能搁置下来了。",
          "拿最简单的小说来举例吧，我想《西游记》大家都耳熟能详，且不往深地说结合作者所在的时代去理解作者要传达的思想，单看小说故事情节是不是非常有意思？或者说时代兴衰里的封建大家庭没落史，饱含儿女情长期期艾艾如《红楼梦》，亦或是金庸的武侠小说？再如现在非常时兴的网络小说，同人文，男频女频仙侠亦或是校园恋爱……数不胜数，当你坐在某处读到一些文字片段感到有意思的时候，就是它存在的意义。",
