          "首先要明确的是在合适的年纪做合适的事，不要越界。非常老土，但是又具有哲理的一句话——“你若盛开，蝴蝶自来。”如果你有自己的闪光点，同样可以成为人群里闪闪发光的宝石。你可以找个合适的时机先表达你的心意，坦白你的想法，做一只热烈且开朗的“小狗”，要知道小狗可是会一直爱自己的主人的。",
          "等到时机成熟以后，两情相悦那就坚定地牵起对方的手。但世间也并非总是如此完美。我希望你能明白的是，人和人之间不一定只能拥有一种关系，没有机会成为恋人，也可以作为知心好友陪伴在对方的身边。倘若对方过度影响你，或者你无法主宰自己的想法，那就潇洒一点，大踏步地往前走自己的路。",
