          "老黑同学你好，高中三年读书是比较辛苦的，但是也是充实的，在高中三年会是我们人生中学习知识最多的阶段，你的未来都会因为这三年的学习而受益。我的高中三年就是在老师的督促下，跟随老师们的步伐学习以及和高中朋友们一起学学闹闹下完成，是非常怀念的三年。学习计划是一定要把数学，英语，物理（或者历史）好好学习好，这是新高考最拉分的科目，当然其他也要好好学习，不过这三科不要偏科哈。"
