          "1.苦中有乐吧，虽然每天早起晚睡，每天要上很多课，但每天都很充实，还有一学校的人和你一起上学，同学之间也会发生很多有意思的事，回过头来看觉得高中还挺有意思的。",
          "2.平平淡淡地过，感觉高中三年还挺快的，高一高二稍微轻松一点，高三快节奏，基本天天都关在学校，不过可以给自己培养个小兴趣，周末或者假期放松一下，这样在学校也有盼头",
          "3.可以每天搞一个学习计划，计划今天一天要完成哪些任务，不过高中一般老师都给你规划好了，跟着老师的节奏走就好，像国庆这种长假可以搞个学习计划，查漏补缺一下"
