          "但是现在每当听到初高中生的上课时间还是会觉得惊讶，感叹中学生活如此之苦。不过没关系，你们现在正身处其中，所以我的经历来看，应该不会觉得苦，哈哈。我高中三年都是在老师和学校的安排下度过的，每天做什么作业、假期什么时候回学校上课等等，我几乎没有自己安排的自由时间，所以跟着老师的安排按部就班了。",
          "也没有什么学习计划，因为忙于完成老师布置的任务，不过有一个宏大的学习目标，考上清华北大，先别管考不考得上，反正当时才高一高二，一切未定，想美了就行。"
