          "高中我过得很单调，每天两点一线，家和学校之间，课间复盘、上课学习、晚上写作业，周末补课，听不懂还要自己找网课看，但每每弄懂一些题型之后，是发自内心的愉快，每每刷题都会有新的感悟，这些学习方法和思维在未来也让我受益匪浅，好好体验这弥足珍贵的三年吧老黑加油！",
