          "文科最大的用处是塑造你的人生观和价值观，因为生活不是只需要文艺，更需要迎合当下社会所需要的东西，文科相比之下优势很少，但是所需很多，要求也没有那么高，像文员，白领，销售，顾问之类的，就很多，学会把拥有的和需要的平衡好，不要求绝对的唯一答案，本身事物就在不停地变化；高考不难，而且高考以后你还有很多的机会去得到高考没有得到的东西，把心放平，不是只有一次机会，压力不要太大。（比如说，你可以参加社会高考，可以升学之类的，如果你大学毕业之后不满意，在校不满意专业也是可以转的）",
