        "lines": [
          "大学学分主要是靠上课获得，社团活动只是作为兴趣爱好发展的地方，一般是不可以加分的。但是大学里加入学生组织（学生会一类），可以加综合考评分，这个分用于算到大学评奖评优里。同时这些个地方有利有弊，可能会很累，也可能遇到一些志同道合同频的好朋友……最后，以我所在的西南大学为例，学校从2026年开始上线第二课堂平台（也就是把社会实践类和一些比赛什么的，除去上课的活动统称为第二课堂），参与第二课堂活动可以获得第二课堂积分，到毕业时会形成第二课堂成绩单（可能会成为找工作的一个依据，只是可能，因为这个东西刚刚起步），再者就是可以通过第二课堂积分换取学分（西南大学10二课积分=1学分），也算是賺取学分的一个途径。当然，肯定还是上课为主要途径，我后面介绍到的第二课堂，各个学校因校而异，可能有其他模式，只是一个简单介绍和补充  ◝ ⩊ ◜.ᐟ对咯，第二课堂里把C3及其以上驾照列为了加分项，可以获得20个二课积分，变相地来说，也就有了获取学分的机会。实习的话，可能都还是需要这个经历的，一般自己找的话就是大三大四。像我这种师范生，就是固定的大三下学期都要出去实习的，实习的学校一般也都是和学校有合作的。非师范的其他专业我确实不太了解呢"
        ]
