        "lines": [
          "杨同学你好，我是一名大三的会计学学姐，财经类专业范围很广，大致分为经济类和管理类，我的专业算财经的管理类。想学财经类专业其实不一定要理科或者文科，一般来说可能理科生更多，但不影响，我就是理科生被会计录取了，你擅长什么科目就可以选什么科目。",
          "现在就没有什么所谓的好就业的工作，就算会计这种万金油专业，哪儿都能去，但工资却低得吓人。好的财经类学校很多，四财一贸算一种吧，上海财经，中央财经，西南财经，中南财经政法和对外经济贸易，都是很好的211双一流学校。高考分数当然不嫌多，考得越高选择越多嘛，如果你想考很好的财经类学校，理科分数得六百往上走了，会很辛苦。",
          "祝你学业有成，能被喜欢的学校和专业录取。"
        ]
