          "我自己读的是人力资源管理，相对于其他几个专业来讲，人力资源管理的就业范围更广。如果你想去好一点的财经类院校，比如说西南财经政法大学之类的，我自己高考那一年录取分数线最低605分。但是像其他的综合性大学，分数线就会稍微低一些，比如我就读的学校2022年在浙江的最低录取分数线是595分，我自己当年是600分招录进的。",
          "当时大一是工商管理大类，后来大二经过考试答辩分流到人力资源管理。"
