          "其次，财经类的专业只是相对于其他文科类专业好就业，如果不是非要选文科，慎重考虑。如果你是一名对理科有兴趣的学生，那么建议选择理科，专业面非常广，就业选择也会很多。选择理科就必须物化捆绑（其实都对数学有要求哈哈哈哈）好学校非常多，你可以根据你的喜好选择，前提是分数够~我是广西考生，高考分数是六百，我建议在这种就业趋势下，尽全力考到六百分及以上是最好的。",
