          "第二条路的话则是考研，如果你的本科院校足够好，那么你就可以直接考本校。不然的话一般都是往外考，或者说是往更加高一个层次的考。例如从双非考到双一流，从双一流考到211，从211考到985。这边并不建议跨考，跨考涉及的知识层面的东西会非常多。"
