          "你问到人啦！我高考英语145哦嘻嘻嘻，首先是最重要的单词！！容我推荐你去B站上搜索一个记单词很好用的方法，up主叫晴儿Patricia，方法叫A4纸记单词法，超级好用！用这个记单词手拿把掐！语法短语记不好，这个就只能多写多记，每个单词都有对应的语法等，先记住单个的单词，再去对应扩展记语法，感兴趣的话，推荐你去看一些美剧磨耳朵，提高听力能力，唐顿庄园的口语很地道，推荐你去看；很迷茫是正常的，我直到现在大三了才想清楚一点，自己想要干什么做什么，不着急，你才高一，慢慢探索，多去认识一些对应职位的人，向他们了解，比如警察朋友，医生朋友，多去问多去打听，也可以多上网搜索，想要克服迷茫，就得靠你自己去探索，加油吧！！另外真的非常敬佩这位班主任！想出这样的方法为孩子们排忧解难，真是太厉害了！有这样的好班主任，相信你们未来发展一定能越来越好～加油！"
