          "1.跟着学校的计划走就好，休息的时候一定要好好休息，学习的时候也要沉浸其中不要三心二意。",
          "2.薄弱科目更应该完成平时布置的基础题，不要直接越过基础题去做难题，也不要单纯靠数量堆积。如果老师布置的任务都不能完成，或者做完了错误率也很高，那表示你并没有掌握相关知识点，刷再多的题和更难的题毫无用处。",
          "3.你能通过中考这个选拔性的考试就证明你并不笨，不要首先就否定了自己。任何事情从0到1都是艰难的，希望你相信自己，题做错了就搞清楚哪错了重复重复再重复，背不下来的内容就今天背一遍明天背一遍后天再背一遍，相信重复的力量，突然有一天你会发现你已经在从1到100的路上了。"
