          "8.谢谢你呢，虽然我只是一个大一新生。在你身上我看到了我的影子。我也想保持一颗孩子心，以阳光视角看待世界，送你一句小王子里面的话正是因为“你为玫瑰花费了时间，才让它变得如此宝贵”。做你也能保持一颗孩子心，生活充满阳光，加油，为你的梦想奋斗，结果不会辜负你的努力，感受大好的青春年华。"
