          "到了高考结束，她考得不是很理想，她没有报新闻，我问她那么喜欢为什么不去，她说分太低了上不了梦校，家里有新闻的从业者觉得前景不好，张雪峰也说新闻没前途。我觉得惋惜，但我理解她的选择，因为我们没有办法不为未来的生活考虑。",
          "大学这几年我们交流的不多，大家都有各自要忙的事，都在被推着长大。前段时间我们两个都在准备保研，久违地因为同一件事可以天天一起吐槽。她准备跨专业到新闻，我当时有一瞬间恍惚，然后意识到她其实没怎么变，还是高中那个在别人说新闻不好的时候因为喜欢和梦想为之辩护的人。",
          "我知道她过去三年过得不好，我特别特别替她开心，兜兜转转她还是选择了自己喜欢的事情，即便过程无比艰难，好在结果是好的。我们现在依旧很难说这条路到底对不对，但至少是我们这一刻坚定不移选择的路，我们也愿意为之承担后果。",
          "所以抱歉学姐没有办法告诉你一个明确的答案，在现在这个社会坚定理想主义是一件很难的事，无论怎么选都会失去一些东西，所以不妨问问你自己，你的热爱能否支撑你走下去，能否让你觉得你为之舍弃的东西是值得的，做出你当下觉得正确的选择就好。不管结果怎样未来的你都会感激现在的你，因为能选择一条道路并坚定地走下去本身就需要很大的勇气。我们还年轻，还有很多时间，很多试错的机会。",
