          "2.事实上，现在的就业市场不太好，我觉得影响就业主要有两个方面的因素第1个因素在于个人的能力。如果想就业的话可以提前去找一些实习经历，第2个因素在于自己所学的专业，如果你刚好学的专业在风口浪尖上，那么就业是相对好一点的。但是现在你年纪还很小。你上大学的时候可能就两年后这样子，社会变化的会非常快，所以不用过度地去担心和焦虑。只要踏实走好每一步就可以了。",
