          "另外，分数决定不了你的人生，人生是旷野不是轨道，无论你的分数最后是否符合你的预期，你的人生依旧有很多很多的美好与可能，当然，能考出一个好分数也必然会给你打人生提供莫大的便利与助力，加油！"
