          "我是重庆大学23级光电的一名学长，刷到你的问题此时正好在重庆大学虎溪校区操场跑步，很高兴你在这么早的时候就确定了自己的目标，高考考多少分可以上重大，对于不同省区这实在是一个比较难回答的问题，你可以参考一下往年的重大分数线和录取位次。对于高中的学习，我认为有太多种办法去自律，在各方各面也有无数的学习方法。但是作为学长，我能给你的建议只有一条，就是尽可能地克服自己的本能去学习，或者说是走出舒适区，择难路，未有疑。在物理学有一个特别简单的理论，对于相同的功，你用的力越大，所需的位移就越小，你用的力越小，所需的位移就越长，学习也是这样，你克服的困难越大，思考的深度越深，就可以有更高的学习效率，反之，如果你不动脑，一味刷题，你所需的位移也就是时间就越长。一定不要做那些看似有用但是你觉得很舒服的事情，比如无脑的刷题。",
          "人总是希望在自己的科目进行深耕，但是至少对于高考分数来说，你必须要全面综合才能上985院校。同时对于自己每天的学习安排，优先做自己最不想做，觉得最难做的任务，这样后续的任务你就会觉得非常简单。克服自己的本能，迈出舒适区，抱着这样的信念和目标，我相信你可以完成自己的目标。在重庆大学的四年，我也是抱着这样的学习生活理念，以一个别人看上去比较轻松，或者说以一个非常高的学习效率，考取了中国科学技术大学的研究生。",
