          "选为积极分子后，经过一年基层党组织培养学习，参加学院理论考试，合格后推送至学校党委进一步学习考核，成为发展对象；发展对象考核通过，经学校党委审批成为预备党员，再经过一年考察期，正式转为中共党员。整个过程不允许挂科、违纪，一旦挂科会直接终止发展，每一个环节都要公示，接收大家监督反馈。",
          "外卖有可能会被偷，有可能是被其他人偷走了也有可能是你们的学长学姐（小猫小狗）拿走去吃了。食堂有一般一个月800-1500包饭，但是有点累，下课就要跑过去",
